export const READINESS_PAGE_HTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PQ Radar — Readiness</title>
<style>
  .viz-root {
    color-scheme: dark;
    color: #ffffff;
    background: #0d0d0d;
    min-height: 100vh;
    --surface-1:      #1a1a19;
    --surface-2:      #0d0d0d;
    --text-primary:   #ffffff;
    --text-secondary: #c3c2b7;
    --text-muted:     #898781;
    --gridline:       #2c2c2a;
    --border:         rgba(255,255,255,0.10);
    --status-good:      #0ca30c;
    --status-warning:   #fab219;
    --status-critical:  #e66767;
    --status-unknown:   #898781;
  }

  * { box-sizing: border-box; }
  html, body {
    margin: 0; padding: 0;
    background: #0d0d0d; color: #ffffff;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  .page { max-width: 1400px; margin: 0 auto; padding: 32px 20px 64px; }
  h1 { font-size: 22px; font-weight: 600; margin: 0 0 4px; }
  h1.page-title { font-size: 44px; font-weight: 800; letter-spacing: -0.02em; margin: 0 0 6px; }
  .subtitle { color: var(--text-secondary); font-size: 14px; margin: 0 0 8px; }
  .tagline { font-size: 18px; font-weight: 500; color: var(--text-secondary); margin: 0 0 14px; }
  .network-flow {
    background: var(--surface-1);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
    margin: 20px 0;
    text-align: center;
    overflow-x: auto;
  }
  .network-flow img { max-width: 100%; width: 100%; height: auto; }

  #gate {
    max-width: 360px; margin: 80px auto; background: var(--surface-1);
    border: 1px solid var(--border); border-radius: 8px; padding: 24px;
  }
  #gate p { color: var(--text-secondary); font-size: 14px; margin: 0 0 16px; }
  #gate input {
    width: 100%; padding: 8px 10px; font-size: 14px; border: 1px solid var(--border);
    border-radius: 6px; background: var(--surface-2); color: var(--text-primary); margin-bottom: 12px;
  }
  #gate button { width: 100%; padding: 8px 10px; font-size: 14px; font-weight: 600; border: none;
    border-radius: 6px; background: var(--status-good); color: #fff; cursor: pointer; }
  #gate .error { color: var(--status-critical); font-size: 13px; margin: -4px 0 12px; }

  .toolbar { display: flex; gap: 10px; margin: 20px 0; flex-wrap: wrap; }
  .toolbar button {
    padding: 8px 14px; font-size: 13px; font-weight: 600; border: 1px solid var(--border);
    border-radius: 6px; background: var(--surface-1); color: var(--text-primary); cursor: pointer;
  }
  .toolbar button:disabled { opacity: 0.5; cursor: default; }
  .toolbar .status { font-size: 12px; color: var(--text-muted); align-self: center; }

  #scan-log, .log-panel {
    display: none;
    background: var(--surface-2); border: 1px solid var(--border); border-radius: 8px;
    padding: 10px 12px; margin: 0 0 20px; max-height: 260px; overflow-y: auto;
    font-family: ui-monospace, "SF Mono", Consolas, monospace; font-size: 12px; line-height: 1.6;
    color: var(--text-secondary); white-space: pre-wrap; word-break: break-all;
  }
  #scan-log .hdr, .log-panel .hdr { color: var(--text-primary); font-weight: 600; }

  .tile { background: var(--surface-1); border: 1px solid var(--border); border-radius: 8px; padding: 14px 16px; }
  a.tile { display: block; text-decoration: none; color: inherit; transition: border-color .12s ease, background .12s ease; }
  a.tile:hover { border-color: var(--text-secondary); background: rgba(255,255,255,0.02); }
  .tile .label { font-size: 12px; color: var(--text-secondary); margin-bottom: 6px; }
  .tile .value { font-size: 26px; font-weight: 600; margin-bottom: 6px; }
  .tile .desc { font-size: 11px; color: var(--text-muted); line-height: 1.4; }

  .stat-tile {
    background: var(--surface-1); border: 1px solid var(--border); border-radius: 10px;
    padding: 16px 18px; box-shadow: 0 1px 0 rgba(255,255,255,0.03) inset;
  }
  .stat-tile-label { font-size: 12px; font-weight: 600; color: var(--text-secondary); margin-bottom: 8px; }
  .stat-tile-total { font-size: 34px; font-weight: 700; color: var(--text-primary); line-height: 1; margin-bottom: 10px; letter-spacing: -0.02em; }
  .stat-tile-row { display: flex; gap: 8px; flex-wrap: wrap; }
  .stat-chip {
    font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 999px;
    display: inline-flex; align-items: center; gap: 5px;
  }
  .stat-chip.good     { background: rgba(12,163,12,0.16);   color: #3fd63f; }
  .stat-chip.critical { background: rgba(230,103,103,0.16); color: #ff9a9a; }
  .stat-chip .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; display: inline-block; }

  .overview { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin: 24px 0; align-items: start; }
  .tile-group-panel {
    background: linear-gradient(165deg, var(--surface-1), var(--surface-2));
    border: 1px solid var(--border); border-radius: 12px; padding: 18px 20px;
  }
  .tile-group-title {
    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em;
    color: var(--text-muted); margin: 0 0 14px; display: flex; align-items: center; gap: 8px;
  }
  .panel-link {
    margin-left: auto; font-size: 11px; font-weight: 600; text-transform: none;
    letter-spacing: 0; color: var(--text-secondary); text-decoration: none;
  }
  .panel-link:hover { color: var(--text-primary); text-decoration: underline; }
  .health-dot { width: 8px; height: 8px; border-radius: 50%; display: none; }
  .health-dot.warn { display: inline-block; background: var(--status-warning); }
  .health-dot.bad { display: inline-block; background: var(--status-critical); }

  .tile-row { display: grid; grid-template-columns: repeat(2, minmax(0, 150px)); gap: 10px; justify-content: start; }
  .tile-group-panel.wide { grid-column: 1 / -1; }
  .tile-group-panel.wide .tile-row { grid-template-columns: repeat(auto-fill, minmax(150px, 190px)); }
  a.stat-tile { display: block; text-decoration: none; color: inherit; transition: border-color .12s ease; }
  a.stat-tile:hover { border-color: var(--text-secondary); }

  .coverage-card {
    background: var(--surface-1); border: 1px solid var(--border); border-radius: 8px;
    padding: 18px 20px; margin-bottom: 20px;
  }
  .coverage-headline { font-size: 18px; font-weight: 600; margin: 0 0 12px; }
  .coverage-bar {
    display: flex; width: 100%; height: 28px; border-radius: 6px; overflow: hidden;
    background: var(--gridline);
  }
  .coverage-bar .seg { display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 600; color: #fff; white-space: nowrap; overflow: hidden; }
  .coverage-bar .seg.covered { background: var(--status-good); }
  .coverage-bar .seg.uncovered { background: var(--text-muted); }
  .coverage-legend { display: flex; gap: 20px; margin-top: 10px; font-size: 12px; color: var(--text-secondary); }
  .coverage-legend .swatch { display: inline-block; width: 10px; height: 10px; border-radius: 2px; margin-right: 6px; vertical-align: middle; }
  .coverage-legend .swatch.covered { background: var(--status-good); }
  .coverage-legend .swatch.uncovered { background: var(--text-muted); }

  h2.section-title { font-size: 16px; font-weight: 600; margin: 32px 0 12px; }
  .muted { color: var(--text-muted); }

  #app { display: none; }
  #loading, #error-banner { color: var(--text-secondary); font-size: 14px; }
  #error-banner { color: var(--status-critical); }
</style>
</head>
<body>
<div class="viz-root">
  <div class="page">

    <div id="gate">
      <h1>PQ Radar — Readiness</h1>
      <p>Enter the API secret to view end-to-end readiness.</p>
      <div id="gate-error" class="error" style="display:none">Invalid secret.</div>
      <input id="secret-input" type="password" placeholder="API secret" autocomplete="off">
      <button id="gate-submit">Unlock</button>
    </div>

    <div id="app">
      <h1 class="page-title">PQ Radar</h1>
      <p class="tagline">A poor man's post quantum network readiness tool</p>
      <p class="subtitle">End-to-end readiness: Client to Edge and Origin (Direct)</p>

      <div class="network-flow">
        <img src="data:image/png;base64," alt="Network flow diagram: at every TLS inspection hop (CDN, load balancer, cloud) an attacker without post-quantum protection can harvest encrypted PII now and decrypt it later." />
      </div>

      <div class="toolbar">
        <button id="pull-btn" type="button">Pull zones from Cloudflare</button>
        <button id="scan-all-btn" type="button">Run full scan (CIDR + edges)</button>
        <button id="refresh-btn" type="button">Refresh</button>
        <span class="status" id="toolbar-status"></span>
      </div>

      <pre id="scan-log"></pre>

      <div id="loading">Loading…</div>
      <div id="error-banner" style="display:none"></div>

      <div id="content" style="display:none">
        <h2 class="section-title" style="margin-top:0;">Overview</h2>
        <div class="overview" id="overview">
          <div class="tile-group-panel">
            <p class="tile-group-title">Readiness <span class="health-dot" id="dot-edge-origin"></span></p>
            <div class="tile-row" id="tiles"></div>
          </div>
          <div class="tile-group-panel">
            <p class="tile-group-title">Cloudflare <span class="health-dot" id="dot-edge"></span></p>
            <div class="tile-row" id="cf-tiles"></div>
          </div>
          <div class="tile-group-panel">
            <p class="tile-group-title">Origin Networks <span class="health-dot" id="dot-origin"></span></p>
            <div class="tile-row" id="origin-tiles"></div>
          </div>
          <div class="tile-group-panel">
            <p class="tile-group-title">Coverage</p>
            <div class="tile-row" id="coverage-tiles"></div>
          </div>
          <div class="tile-group-panel wide">
            <p class="tile-group-title">SSH &amp; FTPS <span class="health-dot" id="dot-services"></span><a class="panel-link" href="/readiness/services">View all &rarr;</a></p>
            <div class="tile-row" id="service-tiles"></div>
          </div>
        </div>

        <div class="coverage-card" id="coverage-card">
          <p class="coverage-headline" id="coverage-headline"></p>
          <div class="coverage-bar" id="coverage-bar"></div>
          <div class="coverage-legend">
            <span><span class="swatch covered"></span>Covered by a known zone</span>
            <span><span class="swatch uncovered"></span>No zone points at this IP</span>
          </div>
        </div>
      </div>
    </div>

  </div>
</div>

<script>
(function () {
  var STORAGE_KEY = "pq_radar_secret";
  var gate = document.getElementById("gate");
  var app = document.getElementById("app");
  var gateError = document.getElementById("gate-error");
  var secretInput = document.getElementById("secret-input");

  function getSecret() { return sessionStorage.getItem(STORAGE_KEY); }
  function setSecret(v) { sessionStorage.setItem(STORAGE_KEY, v); }
  function clearSecret() { sessionStorage.removeItem(STORAGE_KEY); }
  function authHeaders() { return { Authorization: "Bearer " + getSecret() }; }

  function escapeHtml(s) {
    if (s === null || s === undefined) return "";
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  // ?redact=1 swaps real subnet CIDRs/labels for consistent fake ones, purely
  // client-side, for taking clean screenshots \\u2014 never touches the underlying
  // data or links (navigation still targets the real cidr), only what's drawn
  // on screen. Same real value always maps to the same fake value within a
  // page load, via fakeMap.
  var redactMode = /[?&]redact=1\\b/.test(window.location.search);
  var fakeMap = {};
  var fakeCounter = 0;
  function fakeFor(real, kind) {
    if (!real) return real;
    if (Object.prototype.hasOwnProperty.call(fakeMap, real)) return fakeMap[real];
    fakeCounter++;
    var fake = kind === "cidr" ? "10.0." + fakeCounter + ".0/24" : "NETWORK-" + fakeCounter;
    fakeMap[real] = fake;
    return fake;
  }
  function maskValue(real, kind) {
    return redactMode ? fakeFor(real, kind) : real;
  }

  // Builds a link into the standalone detail/services pages, carrying the chosen
  // filter as query params instead of client-side view-swapping \\u2014 each drill-down
  // is its own page now, so the filter has to survive the navigation somehow.
  function buildUrl(path, params) {
    var qs = Object.keys(params).map(function (k) {
      return encodeURIComponent(k) + "=" + encodeURIComponent(params[k]);
    }).join("&");
    return qs ? path + "?" + qs : path;
  }

  function overall(h) {
    if (!h.edge_outcome || !h.origin_outcome) return { cls: "unknown", icon: "?", label: "Incomplete data" };
    var edgePq = h.edge_outcome === "pq";
    var originPq = h.origin_outcome === "pq";
    if (edgePq && originPq) return { cls: "good", icon: "\\u2713", label: "Full" };
    if (edgePq || originPq) return { cls: "warning", icon: "\\u25CF", label: "Mixed" };
    return { cls: "critical", icon: "\\u25BC", label: "None" };
  }

  function renderTiles(hosts) {
    var counts = { full: 0, mixed: 0, none: 0, incomplete: 0 };
    hosts.forEach(function (h) {
      var o = overall(h);
      if (o.label === "Full") counts.full++;
      else if (o.label === "Mixed") counts.mixed++;
      else if (o.label === "None") counts.none++;
      else counts.incomplete++;
    });
    var items = [
      { overall: "all", label: "Total", value: hosts.length, desc: "All known hostnames across Dev and QA" },
      { overall: "Full", label: "Full (edge + origin)", value: counts.full, desc: "Both legs negotiated the PQ hybrid group \\u2014 quantum-resistant end-to-end" },
      { overall: "Mixed", label: "Mixed", value: counts.mixed, desc: "PQ on one leg only \\u2014 edge or origin, not both" },
      { overall: "None", label: "None", value: counts.none, desc: "Neither leg reached PQ \\u2014 may still be live on TLS 1.2 / Classical, not necessarily down" },
      { overall: "Incomplete data", label: "Incomplete data", value: counts.incomplete, desc: "Edge or origin has never been probed for this host" }
    ];
    var el = document.getElementById("tiles");
    el.innerHTML = items.map(function (it) {
      return '<a class="tile" href="' + buildUrl("/readiness/detail", { view: "hostnames", overall: it.overall }) + '">' +
        '<div class="label">' + escapeHtml(it.label) + '</div><div class="value">' + it.value + '</div>' +
        '<div class="desc">' + it.desc + '</div></a>';
    }).join("");
  }

  function statTileHtml(label, total, live, dead, href) {
    var inner = '<div class="stat-tile-label">' + escapeHtml(label) + '</div>' +
      '<div class="stat-tile-total">' + total + '</div>' +
      '<div class="stat-tile-row">' +
        '<span class="stat-chip good"><span class="dot"></span>' + live + ' live</span>' +
        '<span class="stat-chip critical"><span class="dot"></span>' + dead + ' dead</span>' +
      '</div>';
    return href
      ? '<a class="stat-tile" href="' + href + '">' + inner + '</a>'
      : '<div class="stat-tile">' + inner + '</div>';
  }

  // Built from whatever account_label values actually appear in the synced
  // data, not a fixed dev/qa pair — supports any number of configured
  // Cloudflare accounts (see env.ts's cfAccounts()) with no UI change needed
  // when an account is added or removed.
  function renderZoneGroups(hosts) {
    var el = document.getElementById("cf-tiles");
    var labels = [];
    hosts.forEach(function (h) {
      if (h.account_label && labels.indexOf(h.account_label) === -1) labels.push(h.account_label);
    });
    labels.sort();
    if (!labels.length) {
      el.innerHTML = '<p class="muted">No accounts configured yet \\u2014 pull zones to populate this.</p>';
      return;
    }
    el.innerHTML = labels.map(function (key) {
      var subset = hosts.filter(function (h) { return h.account_label === key; });
      var dead = subset.filter(function (h) { return h.edge_outcome === "unreachable"; }).length;
      var live = subset.filter(function (h) {
        return h.edge_outcome === "pq" || h.edge_outcome === "classical" || h.edge_outcome === "downgrade" || h.edge_outcome === "intolerant";
      }).length;
      return statTileHtml(key.toUpperCase(), subset.length, live, dead, buildUrl("/readiness/detail", { view: "hostnames", env: key }));
    }).join("");
  }

  function renderOriginGroups(subnets) {
    var el = document.getElementById("origin-tiles");
    if (!subnets.length) {
      el.innerHTML = '<p class="muted">No enabled subnets configured.</p>';
      return;
    }
    el.innerHTML = subnets.map(function (s) {
      var label = s.cidr + (s.label ? " \\u2014 " + s.label : "");
      var displayLabel = redactMode ? maskValue(s.cidr, "cidr") : label;
      return statTileHtml(displayLabel, s.total, s.live, s.dead,
        buildUrl("/readiness/detail", { view: "subnet-origin", cidr: s.cidr, label: label }));
    }).join("");
  }

  function renderUncoveredTile(coverage, uncoveredCount) {
    var el = document.getElementById("coverage-tiles");
    el.innerHTML =
      '<div class="stat-tile">' +
        '<div class="stat-tile-label">Covered</div>' +
        '<div class="stat-tile-total">' + (coverage.covered || 0) + '</div>' +
      '</div>' +
      '<a class="stat-tile" href="' + buildUrl("/readiness/detail", { view: "orphans" }) + '">' +
        '<div class="stat-tile-label">Uncovered Origins</div>' +
        '<div class="stat-tile-total">' + uncoveredCount + '</div>' +
      '</a>';
  }

  function anyAttemptFailed(health) {
    if (!health) return false;
    if (health.latest_attempt_status === "failed") return true;
    if (health.subnets) return health.subnets.some(function (s) { return s.latest_attempt_status === "failed"; });
    return false;
  }

  function updateHealthDot(id, health) {
    var el = document.getElementById(id);
    if (!el) return;
    el.className = "health-dot" + (anyAttemptFailed(health) ? " warn" : "");
  }

  // --- SSH / FTPS: this panel only shows per-subnet summary tiles that link out to the
  // standalone /readiness/services page \\u2014 the full origin table lives there, not here.
  function renderServiceTiles(subnets) {
    var el = document.getElementById("service-tiles");
    if (!subnets.length) {
      el.innerHTML = '<p class="muted">No enabled subnets configured.</p>';
      return;
    }
    el.innerHTML = subnets.map(function (s) {
      var label = s.cidr + (s.label ? " \\u2014 " + s.label : "");
      var href = buildUrl("/readiness/services", { cidr: s.cidr, label: label });
      return '<a class="stat-tile" href="' + href + '">' +
        '<div class="stat-tile-label">' + escapeHtml(label) + '</div>' +
        '<div class="stat-tile-total">' + s.total + '</div>' +
        '<div class="stat-tile-row">' +
          '<span class="stat-chip good"><span class="dot"></span>SSH: ' + s.ssh_live + '</span>' +
          '<span class="stat-chip good"><span class="dot"></span>FTPS: ' + s.ftps_live + '</span>' +
        '</div></a>';
    }).join("");
  }

  function loadServices() {
    fetch("/api/readiness/services", { headers: authHeaders() })
      .then(function (res) { return res.ok ? res.json() : { subnets: [], run_health: {} }; })
      .then(function (data) {
        renderServiceTiles(data.subnets || []);
        var health = data.run_health || {};
        var failed = anyAttemptFailed(health.ssh) || anyAttemptFailed(health.ftps_implicit) || anyAttemptFailed(health.ftps_explicit);
        var dot = document.getElementById("dot-services");
        if (dot) dot.className = "health-dot" + (failed ? " warn" : "");
      })
      .catch(function () { /* isolated add-on feature — fail silently, never disturb the rest of the page */ });
  }

  function renderCoverage(coverage) {
    var total = coverage.total_live_origins || 0;
    var covered = coverage.covered || 0;
    var uncovered = coverage.uncovered || 0;
    var pct = total > 0 ? Math.round((covered / total) * 100) : 0;

    document.getElementById("coverage-headline").textContent =
      covered + " of " + total + " live origins (" + pct + "%) are behind a known Cloudflare zone";

    var coveredPct = total > 0 ? (covered / total) * 100 : 0;
    var uncoveredPct = total > 0 ? (uncovered / total) * 100 : 0;
    var bar = document.getElementById("coverage-bar");
    bar.innerHTML =
      (coveredPct > 0 ? '<div class="seg covered" style="width:' + coveredPct + '%">' + covered + '</div>' : '') +
      (uncoveredPct > 0 ? '<div class="seg uncovered" style="width:' + uncoveredPct + '%">' + uncovered + '</div>' : '');
  }

  function loadReadiness() {
    document.getElementById("loading").style.display = "block";
    document.getElementById("error-banner").style.display = "none";
    fetch("/api/readiness", { headers: authHeaders() })
      .then(function (res) {
        if (res.status === 401) {
          clearSecret();
          showGate("Invalid secret.");
          return null;
        }
        if (!res.ok) throw new Error("request failed: " + res.status);
        return res.json();
      })
      .then(function (data) {
        if (!data) return;
        document.getElementById("loading").style.display = "none";
        document.getElementById("content").style.display = "block";
        var hosts = data.hosts || [];
        var coverage = data.coverage || { total_live_origins: 0, covered: 0, uncovered: 0 };
        var runHealth = data.run_health || {};

        renderTiles(hosts);
        renderCoverage(coverage);
        renderUncoveredTile(coverage, (data.orphans || []).length);
        renderZoneGroups(hosts);
        renderOriginGroups(data.origin_subnets || []);
        updateHealthDot("dot-edge", runHealth.client_to_edge);
        updateHealthDot("dot-origin", runHealth.direct_to_origin);
        var edgeOriginFailed = anyAttemptFailed(runHealth.client_to_edge) || anyAttemptFailed(runHealth.direct_to_origin);
        var dotEdgeOrigin = document.getElementById("dot-edge-origin");
        if (dotEdgeOrigin) dotEdgeOrigin.className = "health-dot" + (edgeOriginFailed ? " warn" : "");
      })
      .catch(function (err) {
        document.getElementById("loading").style.display = "none";
        var banner = document.getElementById("error-banner");
        banner.style.display = "block";
        banner.textContent = "Failed to load readiness data: " + err.message;
      });
  }

  function runAction(btnId, path, label) {
    var btn = document.getElementById(btnId);
    var status = document.getElementById("toolbar-status");
    btn.disabled = true;
    status.textContent = label + "…";
    fetch(path, { method: "POST", headers: authHeaders() })
      .then(function (res) {
        if (!res.ok) throw new Error("request failed: " + res.status);
        return res.json();
      })
      .then(function (data) {
        status.textContent = label + " done: " + JSON.stringify(data);
        btn.disabled = false;
        loadReadiness();
      })
      .catch(function (err) {
        status.textContent = label + " failed: " + err.message;
        btn.disabled = false;
      });
  }

  var logEl = document.getElementById("scan-log");

  function logLine(text, isHeader) {
    var line = document.createElement("div");
    if (isHeader) line.className = "hdr";
    line.textContent = text;
    logEl.appendChild(line);
    logEl.scrollTop = logEl.scrollHeight;
  }

  // Streams a POST endpoint's plain-text NDJSON-derived body line by line into the log
  // panel as it arrives, instead of waiting for the whole response like runAction() does.
  function streamAction(path) {
    return fetch(path, { method: "POST", headers: authHeaders() }).then(function (res) {
      if (!res.body) throw new Error("request failed: " + res.status);
      var reader = res.body.getReader();
      var decoder = new TextDecoder();
      var buffer = "";

      function pump() {
        return reader.read().then(function (result) {
          if (result.done) {
            if (buffer.trim()) logLine(buffer);
            if (!res.ok) throw new Error("request failed: " + res.status);
            return;
          }
          buffer += decoder.decode(result.value, { stream: true });
          var idx;
          while ((idx = buffer.indexOf("\\n")) >= 0) {
            var line = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 1);
            if (line.trim()) logLine(line);
          }
          return pump();
        });
      }

      return pump();
    });
  }

  document.getElementById("pull-btn").addEventListener("click", function () {
    runAction("pull-btn", "/api/zones/pull", "Pulling zones");
  });

  document.getElementById("scan-all-btn").addEventListener("click", function () {
    var btn = document.getElementById("scan-all-btn");
    var status = document.getElementById("toolbar-status");
    btn.disabled = true;
    status.textContent = "Running full scan…";
    logEl.textContent = "";
    logEl.style.display = "block";

    logLine("=== origin scan (CIDR) ===", true);
    streamAction("/trigger")
      .then(function () {
        logLine("=== edge scan (client-to-edge) ===", true);
        return streamAction("/api/zones/scan-edges");
      })
      .then(function () {
        status.textContent = "Full scan done";
        btn.disabled = false;
        loadReadiness();
      })
      .catch(function (err) {
        logLine("--- error: " + err.message + " ---");
        status.textContent = "Full scan failed: " + err.message;
        btn.disabled = false;
      });
  });

  document.getElementById("refresh-btn").addEventListener("click", loadReadiness);

  function showGate(errorMsg) {
    app.style.display = "none";
    gate.style.display = "block";
    if (errorMsg) {
      gateError.textContent = errorMsg;
      gateError.style.display = "block";
    } else {
      gateError.style.display = "none";
    }
  }

  function showApp() {
    gate.style.display = "none";
    app.style.display = "block";
    loadReadiness();
    loadServices();
  }

  document.getElementById("gate-submit").addEventListener("click", function () {
    var v = secretInput.value.trim();
    if (!v) return;
    setSecret(v);
    showApp();
  });
  secretInput.addEventListener("keydown", function (e) {
    if (e.key === "Enter") document.getElementById("gate-submit").click();
  });

  if (getSecret()) {
    showApp();
  } else {
    showGate();
  }
})();
</script>
</body>
</html>
`;
